select

from t_message
where client_msg_id = #{clientMsgId,jdbcType=VARCHAR}
  and target_device_id = #{targetDeviceId,jdbcType=VARCHAR}
limit 1

select

from t_message
where client_msg_id = #{clientMsgId,jdbcType=VARCHAR}
  and (
      from_user = #{fromUser,jdbcType=VARCHAR}
      or from_ref = #{fromRef,jdbcType=VARCHAR}
      or from_user = #{fromRef,jdbcType=VARCHAR}
  )
limit 1

select

from t_message
where client_msg_id = #{clientMsgId,jdbcType=VARCHAR}
  and sync_from_device is null
  and (
      from_user = #{username,jdbcType=VARCHAR}
      or from_ref = #{userRef,jdbcType=VARCHAR}
      or to_user = #{username,jdbcType=VARCHAR}
  )
order by id asc
limit 1

select
from t_message where id in ( select min(t.id) from t_message t where ((t.from_user = #{a,jdbcType=VARCHAR} and t.to_user = #{b,jdbcType=VARCHAR}) or (t.from_user = #{b,jdbcType=VARCHAR} and t.to_user = #{a,jdbcType=VARCHAR})) group by t.client_msg_id )
and id < #{beforeId,jdbcType=BIGINT}
order by id desc limit #{limit,jdbcType=INTEGER}

select

from t_message
where id in (
    select chosen from (
        select coalesce(
            min(case
                when target_device_id = #{deviceId,jdbcType=VARCHAR}
                 and (to_user = #{viewer,jdbcType=VARCHAR} or sync_from_device is not null)
                then id end),
            min(case
                when from_user = #{viewer,jdbcType=VARCHAR}
                 and from_device_id = #{deviceId,jdbcType=VARCHAR}
                then id end),
            min(id)
        ) as chosen
        from t_message
        where ((from_user = #{viewer,jdbcType=VARCHAR} and to_user = #{peer,jdbcType=VARCHAR})
            or (from_user = #{peer,jdbcType=VARCHAR} and to_user = #{viewer,jdbcType=VARCHAR}))
        group by client_msg_id
    ) picked
)

    and id < #{beforeId,jdbcType=BIGINT}

order by id desc
limit #{limit,jdbcType=INTEGER}

select

from t_message
where id in (
    select min(t.id) from t_message t
    where t.from_ref = #{fromRef,jdbcType=VARCHAR}
      and t.to_user = #{toUser,jdbcType=VARCHAR}
    group by t.client_msg_id
)

    and id < #{beforeId,jdbcType=BIGINT}

order by id desc
limit #{limit,jdbcType=INTEGER}

select

from t_message
where id in (
    select chosen from (
        select coalesce(
            min(case
                when target_device_id = #{deviceId,jdbcType=VARCHAR}
                 and (to_user = #{viewer,jdbcType=VARCHAR} or sync_from_device is not null)
                then id end),
            min(case
                when from_device_ref = #{deviceRef,jdbcType=VARCHAR}
                then id end),
            min(id)
        ) as chosen
        from t_message
        where from_ref = #{fromRef,jdbcType=VARCHAR}
          and to_user = #{toUser,jdbcType=VARCHAR}
        group by client_msg_id
    ) picked
)

    and id < #{beforeId,jdbcType=BIGINT}

order by id desc
limit #{limit,jdbcType=INTEGER}

select

from t_message
where target_device_id = #{deviceId,jdbcType=VARCHAR}
  and delivered = 0
  and (
      to_user = #{toUsername,jdbcType=VARCHAR}
      or (from_user = #{toUsername,jdbcType=VARCHAR} and sync_from_device is not null)
  )
  and id > ifnull((
      select cleared_before_id from t_conversation_clear
      where username = #{toUsername,jdbcType=VARCHAR}
        and peer = if(from_user = #{toUsername,jdbcType=VARCHAR},
                      to_user, if(from_ref is not null, from_ref, from_user))
  ), 0)
order by id asc
limit #{limit,jdbcType=INTEGER}

