update t_message
set read_flag = 1
where from_user = #{fromUsername,jdbcType=VARCHAR}
  and to_user = #{toUsername,jdbcType=VARCHAR}
  and read_flag = 0
  and recalled = 0

  and client_msg_id in (
    select client_msg_id from (
      select distinct client_msg_id
      from t_message
      where from_user = #{fromUsername,jdbcType=VARCHAR}
        and to_user = #{toUsername,jdbcType=VARCHAR}
        and id <= #{beforeId,jdbcType=BIGINT}
    ) read_ids
  )

update t_message
set read_flag = 1
where from_ref = #{fromRef,jdbcType=VARCHAR}
  and to_user = #{toUsername,jdbcType=VARCHAR}
  and read_flag = 0
  and recalled = 0

  and client_msg_id in (
    select client_msg_id from (
      select distinct client_msg_id
      from t_message
      where from_ref = #{fromRef,jdbcType=VARCHAR}
        and to_user = #{toUsername,jdbcType=VARCHAR}
        and id <= #{beforeId,jdbcType=BIGINT}
    ) read_ids
  )

